bool32 AW_EvalCond(const struct AwCond *c)
{
    switch (c->kind)
    {
    case AW_COND_NONE:       return FALSE;  // "no test" is never provably true
    case AW_COND_FLAG_SET:   return FlagGet(c->id) == TRUE;
    case AW_COND_FLAG_CLEAR: return FlagGet(c->id) == FALSE;
    case AW_COND_VAR_EQ:     return VarGet(c->id) == c->value;
    case AW_COND_VAR_GE:     return VarGet(c->id) >= c->value;
    case AW_COND_HAS_ITEM:   return CheckBagHasItem(c->id, c->value);
    }
    return FALSE;
}
